13	static void test_create_destroy_empty(void) {
14	    rbtree_t *t = rb_create(NULL);
15	    check(t != NULL, "rb_create returns non-NULL");
16	    check(rb_size(t) == 0, "fresh tree has size 0");
17	    check(rb_find(t, "anything") == NULL, "rb_find on empty tree returns NULL");
18	    rb_destroy(t);
