26	static void test_insert_and_find_single(void) {
27	    rbtree_t *t = rb_create(NULL);
28	    int value = 42;
29	    check(rb_insert(t, "apple", &value) == 0, "insert single key succeeds");
30	    check(rb_find(t, "apple") == &value, "find returns the inserted value");
31	    check(rb_size(t) == 1, "size is 1 after one insert");
32	    rb_destroy(t);
