36	    rbtree_t *t = rb_create(NULL);
37	    int a = 1, b = 2, c = 3;
38	    check(rb_insert(t, "banana", &a) == 0, "insert banana");
39	    check(rb_insert(t, "apple", &b) == 0, "insert apple");
40	    check(rb_insert(t, "cherry", &c) == 0, "insert cherry");
41	    check(rb_find(t, "banana") == &a, "find banana after multiple inserts");
42	    check(rb_find(t, "apple") == &b, "find apple after multiple inserts");
43	    check(rb_find(t, "cherry") == &c, "find cherry after multiple inserts");
44	    check(rb_size(t) == 3, "size is 3 after three distinct inserts");
45	    rb_destroy(t);
46	}
