48	static void test_find_missing_key_returns_null(void) {
49	    rbtree_t *t = rb_create(NULL);
50	    int value = 7;
51	    check(rb_insert(t, "apple", &value) == 0, "insert apple");
52	    check(rb_find(t, "banana") == NULL, "find a never-inserted key returns NULL");
53	    rb_destroy(t);
54	}
