70	static void test_overwrite_frees_old_value(void) {
71	    free_count = 0;
72	    rbtree_t *t = rb_create(counting_free);
73	    int *first  = make_int(1);
74	    int *second = make_int(2);
75	    check(rb_insert(t, "apple", first) == 0, "insert apple with first value");
76	    check(rb_insert(t, "apple", second) == 0, "overwrite apple with second value");
77	    check(free_count == 1, "value_free called exactly once on overwrite");
78	    check(*(int *)rb_find(t, "apple") == 2, "find returns the new value after overwrite");
79	    check(rb_size(t) == 1, "size unchanged after overwrite (no new node)");
80	    rb_destroy(t);
81	    check(free_count == 2, "value_free called again for the remaining node on destroy");
82	}
