84	static void test_overwrite_with_null_value_free_does_not_crash(void) {
85	    rbtree_t *t = rb_create(NULL);
86	    int a = 1, b = 2;
87	    check(rb_insert(t, "apple", &a) == 0, "insert apple");
88	    check(rb_insert(t, "apple", &b) == 0, "overwrite apple with value_free NULL");
89	    check(rb_find(t, "apple") == &b, "find returns new value after NULL-destructor overwrite");
90	    check(rb_size(t) == 1, "size unchanged after overwrite with NULL destructor");
91	    rb_destroy(t);
92	}
