94	#define TEST_MAX_KEYS 8
95	
96	struct order_ctx {
97	    const char *keys[TEST_MAX_KEYS];
98	    size_t      count;
99	};
100	
101	static void collect_key(const char *key, void *value, void *ctx_ptr) {
102	    (void)value;
103	    struct order_ctx *ctx = ctx_ptr;
104	    ctx->keys[ctx->count++] = key;
105	}
