107	static void test_foreach_visits_in_order(void) {
108	    rbtree_t *t = rb_create(NULL);
109	    const char *keys[5] = {"cherry", "apple", "elderberry", "banana", "date"};
110	    int values[5] = {0};
111	    for (int i = 0; i < 5; i++) {
112	        check(rb_insert(t, keys[i], &values[i]) == 0, "insert during foreach setup");
113	    }
114	    struct order_ctx ctx = { .count = 0 };
115	    rb_foreach(t, collect_key, &ctx);
116	    check(ctx.count == 5, "foreach visited every node exactly once");
117	    int sorted = 1;
118	    for (size_t i = 1; i < ctx.count; i++) {
119	        if (strcmp(ctx.keys[i - 1], ctx.keys[i]) >= 0) sorted = 0;
120	    }
121	    check(sorted, "foreach visits keys in strictly increasing strcmp order");
122	    rb_destroy(t);
123	}
