164	static void test_insert_single_root_is_black(void) {
165	    rbtree_t *t = rb_create(NULL);
166	    int value = 1;
167	    check(rb_insert(t, "only", &value) == 0, "insert single key for root-black test");
168	    check(rb_validate(t) == 0, "validate passes on single-node tree (root is black)");
169	    rb_destroy(t);
