196	static void test_insert_descending_triggers_ll_rotation(void) {
197	    /* Mirror of the RR case: c, b, a inserted descending forces the LL
198	     * straight-line case at the root, needing a right rotation at c. */
199	    rbtree_t *t = rb_create(NULL);
200	    int va = 1, vb = 2, vc = 3;
201	    check(rb_insert(t, "c", &vc) == 0, "insert c");
202	    check(rb_insert(t, "b", &vb) == 0, "insert b");
203	    check(rb_insert(t, "a", &va) == 0, "insert a (triggers LL rotation at root)");
204	    check(rb_find(t, "a") == &va, "find a after LL rotation");
205	    check(rb_find(t, "b") == &vb, "find b after LL rotation");
206	    check(rb_find(t, "c") == &vc, "find c after LL rotation");
207	    check(rb_size(t) == 3, "size is 3 after LL-triggering inserts");
208	    check(rb_validate(t) == 0, "validate passes after LL rotation");
209	    struct order_ctx ctx = { .count = 0 };
210	    rb_foreach(t, collect_key, &ctx);
211	    check(ctx.count == 3 && strcmp(ctx.keys[0], "a") == 0 &&
212	          strcmp(ctx.keys[1], "b") == 0 && strcmp(ctx.keys[2], "c") == 0,
213	          "foreach still in order after LL rotation");
214	    rb_destroy(t);
215	}
