217	static void test_insert_triggers_red_uncle_recolor(void) {
218	    /* m, d, t: m is root (black), d and t are its red children (no
219	     * violation). Inserting b (< d) creates a red-red violation (b, d) whose
220	     * uncle t is red -> Case 1: recolor d,t black, m red, then re-blacken m
221	     * since it's root. No rotation needed for this case. */
222	    rbtree_t *t = rb_create(NULL);
223	    int vm = 1, vd = 2, vtt = 3, vb = 4;
224	    check(rb_insert(t, "m", &vm) == 0, "insert m");
225	    check(rb_insert(t, "d", &vd) == 0, "insert d");
226	    check(rb_insert(t, "t", &vtt) == 0, "insert t");
227	    check(rb_insert(t, "b", &vb) == 0, "insert b (triggers red-uncle recolor)");
228	    check(rb_find(t, "m") == &vm, "find m after red-uncle recolor");
229	    check(rb_find(t, "d") == &vd, "find d after red-uncle recolor");
230	    check(rb_find(t, "t") == &vtt, "find t after red-uncle recolor");
231	    check(rb_find(t, "b") == &vb, "find b after red-uncle recolor");
232	    check(rb_size(t) == 4, "size is 4 after red-uncle-triggering inserts");
233	    check(rb_validate(t) == 0, "validate passes after red-uncle recolor");
234	    rb_destroy(t);
235	}
