237	static void test_insert_triggers_lr_triangle_double_rotation(void) {
238	    /* c, a, b: a is c's red left child; b (between a and c) becomes a's red
239	     * right child -- a "triangle" on the left side, uncle (c's right, NIL)
240	     * black. Needs rotate_left(a) to straighten, then rotate_right(c). */
241	    rbtree_t *t = rb_create(NULL);
242	    int vc = 1, va = 2, vb = 3;
243	    check(rb_insert(t, "c", &vc) == 0, "insert c");
244	    check(rb_insert(t, "a", &va) == 0, "insert a");
245	    check(rb_insert(t, "b", &vb) == 0, "insert b (triggers LR double rotation)");
246	    check(rb_find(t, "a") == &va, "find a after LR rotation");
247	    check(rb_find(t, "b") == &vb, "find b after LR rotation");
248	    check(rb_find(t, "c") == &vc, "find c after LR rotation");
249	    check(rb_size(t) == 3, "size is 3 after LR-triggering inserts");
250	    check(rb_validate(t) == 0, "validate passes after LR rotation");
251	    struct order_ctx ctx = { .count = 0 };
252	    rb_foreach(t, collect_key, &ctx);
253	    check(ctx.count == 3 && strcmp(ctx.keys[0], "a") == 0 &&
254	          strcmp(ctx.keys[1], "b") == 0 && strcmp(ctx.keys[2], "c") == 0,
255	          "foreach still in order after LR rotation");
256	    rb_destroy(t);
257	}
258	
259	static void test_insert_triggers_rl_triangle_double_rotation(void) {
260	    /* Mirror of LR: a, c, b -- triangle on the right side, needs
261	     * rotate_right(c) to straighten, then rotate_left(a). */
262	    rbtree_t *t = rb_create(NULL);
263	    int va = 1, vc = 2, vb = 3;
264	    check(rb_insert(t, "a", &va) == 0, "insert a");
265	    check(rb_insert(t, "c", &vc) == 0, "insert c");
266	    check(rb_insert(t, "b", &vb) == 0, "insert b (triggers RL double rotation)");
267	    check(rb_find(t, "a") == &va, "find a after RL rotation");
268	    check(rb_find(t, "b") == &vb, "find b after RL rotation");
269	    check(rb_find(t, "c") == &vc, "find c after RL rotation");
270	    check(rb_size(t) == 3, "size is 3 after RL-triggering inserts");
271	    check(rb_validate(t) == 0, "validate passes after RL rotation");
272	    struct order_ctx ctx = { .count = 0 };
273	    rb_foreach(t, collect_key, &ctx);
274	    check(ctx.count == 3 && strcmp(ctx.keys[0], "a") == 0 &&
275	          strcmp(ctx.keys[1], "b") == 0 && strcmp(ctx.keys[2], "c") == 0,
276	          "foreach still in order after RL rotation");
277	    rb_destroy(t);
278	}
