280	static void test_destroy_single_node(void) {
281	    rbtree_t *t = rb_create(NULL);
282	    int value = 1;
283	    check(rb_insert(t, "only", &value) == 0, "insert single node for destroy test");
284	    rb_destroy(t); /* clean under asan/memcheck is the test */
285	}
