287	static void test_destroy_left_heavy_chain(void) {
288	    /* Descending insertion order with no fixup builds a pure left-child chain
289	     * (e -> d -> c -> b -> a). Exercises the Reach's rotation branch on every
290	     * iteration but the last, on purpose — not incidentally like the existing
291	     * descending-order validate test. */
292	    rbtree_t *t = rb_create(NULL);
293	    const char *keys[5] = {"e", "d", "c", "b", "a"};
294	    int values[5] = {0};
295	    for (int i = 0; i < 5; i++) {
296	        check(rb_insert(t, keys[i], &values[i]) == 0, "insert descending for left-heavy chain");
297	    }
298	    rb_destroy(t); /* clean under asan/memcheck is the test */
299	}
300	
301	static void test_destroy_calls_value_free_once_per_node(void) {
302	    free_count = 0;
303	    rbtree_t *t = rb_create(counting_free);
304	    const char *keys[5] = {"cherry", "apple", "elderberry", "banana", "date"};
305	    for (int i = 0; i < 5; i++) {
306	        check(rb_insert(t, keys[i], make_int(i)) == 0, "insert heap value for destroy-count test");
307	    }
308	    rb_destroy(t);
309	    check(free_count == 5, "value_free called exactly once per node on destroy");
310	}
